def compute(vars):
    v1 = vars["v1"]
    v2 = vars["v2"]
    greatest_amount = max(v1, v2)
    return {
        "value": greatest_amount,
        "trace": {
            "v1_2017": v1,
            "v2_2016": v2,
            "greatest_amount": greatest_amount,
            "output_meta": {
                "currency": "USD",
                "scale": "million",
                "unit": None
            }
        }
    }
